import { useMemo, useState } from "react";
import { ArrowDownRight, ArrowRight, Bell, Check, CheckCircle2, ClipboardList, Download, ExternalLink, FileText, HeartHandshake, Languages, LockKeyhole, MapPinned, MessageSquareWarning, MoreHorizontal, Navigation, PhoneCall, RefreshCw, Send, ShieldAlert, SlidersHorizontal, Sparkles, TriangleAlert, UserRound, UsersRound, Wifi, WifiOff } from "lucide-react";
import { toast } from "sonner";
import { Link } from "wouter";
import { trpc } from "@/lib/trpc";
import { Card, DemoLabel, PageHeader, ProgressBar, SectionTitle, SignalBridgeShell, SignalMap, StatusPill } from "@/components/SignalBridgeShell";

const formatTime = (date: Date | string | null | undefined) => date ? new Date(date).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", timeZone: "Asia/Kolkata" }) : "—";
const formatDate = (date: Date | string | null | undefined) => date ? new Date(date).toLocaleDateString([], { day: "2-digit", month: "short", year: "numeric" }) : "—";
const severityTone = (severity?: string) => severity === "critical" || severity === "high" || severity === "warning" ? "red" : severity === "moderate" || severity === "watch" ? "amber" : severity === "advisory" ? "cyan" : "green";
const priorityTone = (priority?: string) => priority === "now" ? "red" : priority === "next" ? "amber" : "green";

function Workspace({ children }: { children: React.ReactNode }) { return <SignalBridgeShell><div className="mx-auto max-w-[1480px] px-5 py-7 md:px-8 md:py-9">{children}</div></SignalBridgeShell>; }
function LoadingCard() { return <Card className="p-6"><div className="h-4 w-32 animate-pulse rounded bg-[#e7eef1]" /><div className="mt-4 h-8 w-3/4 animate-pulse rounded bg-[#e7eef1]" /><div className="mt-3 h-3 w-full animate-pulse rounded bg-[#eef3f5]" /></Card>; }
function NextPhaseNotice({ text = "AI interpretation, Tamil generation, voice output and automated geospatial calculations are coming in next integration phase." }: { text?: string }) { return <div className="flex gap-3 rounded-xl border border-dashed border-[#b9ccd3] bg-[#f8fbfc] p-4 text-sm text-[#5c6d79]"><Sparkles size={17} className="mt-0.5 shrink-0 text-[#2e8b91]" /><div><div className="font-semibold text-[#27445b]">Coming in next integration phase</div><div className="mt-1 leading-5">{text}</div></div></div>; }

export function DashboardPage() {
  const { data, isLoading, refetch } = trpc.signalbridge.snapshot.useQuery();
  const [checkedIn, setCheckedIn] = useState(false);
  if (isLoading || !data) return <Workspace><PageHeader eyebrow="COMMAND / OVERVIEW" title="Emergency dashboard" description="Loading the latest SignalBridge snapshot." /><div className="mt-7 grid gap-5 md:grid-cols-2"><LoadingCard /><LoadingCard /></div></Workspace>;
  const activeWarning = data.warnings.find(w => w.status === "active") ?? data.warnings[0];
  const completed = data.actionPlans.filter(plan => plan.status === "complete").length;
  const corroboratedReports = data.citizenReports.filter(report => report.verificationStatus === "corroborated" || report.verificationStatus === "triaged").length;
  return <Workspace>
    <PageHeader eyebrow="COMMAND / OVERVIEW" title="Emergency dashboard" description="A structured view of what is happening, what is trusted, and what to do next in the Chennai flood demonstration environment." action={<div className="flex items-center gap-2"><DemoLabel /><button onClick={() => refetch()} className="sb-focus inline-flex items-center gap-2 rounded-lg border border-[#cbd9df] bg-white px-3 py-2 text-xs font-semibold text-[#27445b] transition hover:border-[#7fb8bf]"><RefreshCw size={14} /> Refresh</button></div>} />
    <div className="mt-7 flex flex-wrap items-center gap-3 rounded-xl border border-[#e7d19d] bg-[#fff8e8] px-4 py-3 text-sm text-[#6f5019]"><TriangleAlert size={17} className="text-[#d39124]" /><span className="font-semibold">Active emergency status:</span><span>{activeWarning.title}</span><span className="ml-auto font-mono text-[10px] uppercase tracking-[.12em]">Valid until {formatTime(activeWarning.validUntil)} IST</span></div>
    <div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Localized risk" value="HIGH" detail="Perambur / North Chennai" tone="red" icon={<ShieldAlert size={18} />} /><Metric label="Active warnings" value={String(data.warnings.length).padStart(2, "0")} detail="2 sources · all current" tone="cyan" icon={<RadioIcon />} /><Metric label="Action readiness" value={`${completed}/${data.actionPlans.length}`} detail="Steps prepared for you" tone="green" icon={<ClipboardList size={18} />} /><Metric label="Community pulse" value={`${corroboratedReports}/${data.citizenReports.length}`} detail="Reports triaged or corroborated" tone="amber" icon={<UsersRound size={18} />} /></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.1fr_.9fr]">
      <div className="space-y-5"><Card className="overflow-hidden"><div className="flex flex-wrap items-start justify-between gap-4 border-b border-[#e4ebee] p-5 md:p-6"><div><div className="flex items-center gap-2"><StatusPill tone={severityTone(activeWarning.severity)}>{activeWarning.severity}</StatusPill><span className="font-mono text-[10px] uppercase tracking-[.11em] text-[#84949d]">Issued {formatTime(activeWarning.issuedAt)} IST</span></div><h2 className="mt-3 max-w-[560px] font-display text-2xl font-semibold tracking-[-.035em] text-[#0d1b2a]">{activeWarning.title}</h2><p className="mt-2 max-w-[620px] text-sm leading-6 text-[#5c6d79]">{activeWarning.summary}</p></div><Link href="/alerts" className="sb-focus inline-flex items-center gap-1.5 rounded-lg border border-[#cbd9df] bg-white px-3 py-2 text-xs font-semibold text-[#27445b] hover:border-[#7fb8bf]">Review alerts <ArrowRight size={14} /></Link></div><div className="grid gap-3 p-5 md:grid-cols-3 md:p-6"><div className="rounded-lg bg-[#f4f7f9] p-3"><div className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">Affected area</div><div className="mt-2 text-sm font-semibold text-[#27445b]">{activeWarning.area}</div></div><div className="rounded-lg bg-[#f4f7f9] p-3"><div className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">Warning source</div><div className="mt-2 text-sm font-semibold text-[#27445b]">{activeWarning.sourceLabel}</div></div><div className="rounded-lg bg-[#f4f7f9] p-3"><div className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">Trust state</div><div className="mt-2 flex items-center gap-1.5 text-sm font-semibold text-[#2e8b70]"><CheckCircle2 size={15} /> Official + corroborated</div></div></div></Card><Card className="p-5 md:p-6"><SectionTitle eyebrow="ACTIONFORGE / CURRENT PLAN" title="Your next safe actions" action={<Link href="/action-plans" className="sb-focus text-xs font-semibold text-[#2e8b91] hover:underline">Open full plan →</Link>} /><div className="space-y-3">{data.actionPlans.slice(0, 3).map((plan, index) => <div key={plan.id} className="flex gap-3 rounded-lg border border-[#e4ebee] p-3"><div className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-xs font-bold ${plan.status === "complete" ? "bg-[#daf0e8] text-[#21684f]" : plan.status === "in_progress" ? "bg-[#fff2d4] text-[#7d5411]" : "bg-[#e8eef4] text-[#27445b]"}`}>{plan.status === "complete" ? <Check size={15} /> : index + 1}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="font-semibold text-[#27445b]">{plan.title}</span><StatusPill tone={priorityTone(plan.priority)}>{plan.priority === "now" ? "Now" : plan.priority === "next" ? "Next" : "Ready"}</StatusPill></div><div className="mt-1 text-xs leading-5 text-[#71818b]">{plan.description}</div></div></div>)}</div></Card></div>
      <div className="space-y-5"><Card className="overflow-hidden"><div className="flex items-center justify-between p-5 pb-3 md:p-6 md:pb-3"><SectionTitle eyebrow="GEOSHIELD / LOCAL VIEW" title="Risk around you" /><Link href="/risk-map" className="sb-focus text-xs font-semibold text-[#2e8b91] hover:underline">Open map →</Link></div><div className="px-5 pb-5 md:px-6 md:pb-6"><SignalMap compact /></div><div className="flex items-center gap-4 border-t border-[#e4ebee] px-5 py-3 text-[10px] font-mono uppercase tracking-[.1em] text-[#84949d] md:px-6"><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#c75252]" /> Severe</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#dd9c30]" /> Moderate</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#2e8b70]" /> Lower</span></div></Card><Card className="p-5 md:p-6"><SectionTitle eyebrow="SAFELOOP / CHECK-IN" title="Safety status" action={<StatusPill tone={checkedIn ? "green" : "amber"}>{checkedIn ? "Safe" : "Needs check-in"}</StatusPill>} /><p className="text-sm leading-6 text-[#5c6d79]">{checkedIn ? "Thanks — your status is current. We will keep monitoring for changes in your area." : data.safety.message}</p><div className="mt-4 flex flex-wrap gap-2"><button onClick={() => { setCheckedIn(true); toast.success("Safety status updated", { description: "Your check-in is recorded for this demo session." }); }} className="sb-focus inline-flex items-center gap-2 rounded-lg bg-[#0d3448] px-3.5 py-2.5 text-xs font-semibold text-white hover:bg-[#174a60]"><CheckCircle2 size={15} /> {checkedIn ? "Checked in" : "I am safe"}</button><Link href="/safety" className="sb-focus inline-flex items-center gap-2 rounded-lg border border-[#cbd9df] bg-white px-3.5 py-2.5 text-xs font-semibold text-[#27445b] hover:border-[#7fb8bf]">View status</Link></div></Card></div>
    </div>
    <div className="mt-5"><NextPhaseNotice /></div>
  </Workspace>;
}

function Metric({ label, value, detail, tone, icon }: { label: string; value: string; detail: string; tone: "red" | "cyan" | "green" | "amber"; icon: React.ReactNode }) { const palette = { red: "text-[#b64242] bg-[#fde5e3]", cyan: "text-[#0d5960] bg-[#d9f1f0]", green: "text-[#21684f] bg-[#daf0e8]", amber: "text-[#7d5411] bg-[#fff2d4]" }; return <Card className="p-4"><div className="flex items-start justify-between"><div className="font-mono text-[9px] uppercase tracking-[.15em] text-[#84949d]">{label}</div><div className={`rounded-lg p-2 ${palette[tone]}`}>{icon}</div></div><div className="mt-5 font-display text-3xl font-semibold tracking-[-.04em] text-[#0d1b2a]">{value}</div><div className="mt-1 text-xs text-[#71818b]">{detail}</div></Card>; }
function RadioIcon() { return <div className="relative h-[18px] w-[18px]"><span className="absolute left-[6px] top-[6px] h-2 w-2 rounded-full bg-current" /><span className="absolute left-[3px] top-[3px] h-3.5 w-3.5 rounded-full border border-current opacity-60" /><span className="absolute left-0 top-0 h-[18px] w-[18px] rounded-full border border-current opacity-30" /></div>; }

export function AlertsPage() {
  const { data: warnings, isLoading } = trpc.signalbridge.warnings.useQuery();
  const { data: rawAlert } = trpc.signalbridge.rawDemoAlert.useQuery();
  const { data: defaultIntelligence } = trpc.signalbridge.alertIntelligence.useQuery();
  const interpret = trpc.signalbridge.interpretAlert.useMutation();
  const [draft, setDraft] = useState<Record<string, string> | null>(null);
  const [interpreted, setInterpreted] = useState<typeof defaultIntelligence>();
  const current = draft ?? (rawAlert ? { ...rawAlert } : null);
  const updateDraft = (field: string, value: string) => setDraft({ ...(current ?? {}), [field]: value });
  const runInterpretation = () => {
    if (!current) return;
    interpret.mutate(current as Parameters<typeof interpret.mutate>[0], { onSuccess: setInterpreted });
  };
  const intelligence = interpreted ?? defaultIntelligence;
  return <Workspace>
    <PageHeader eyebrow="SIGNALCORE / ALERT INTELLIGENCE" title="Alert intelligence" description="Convert a raw warning into structured emergency intelligence while keeping source provenance and demo boundaries visible." action={<div className="flex items-center gap-2"><DemoLabel /><StatusPill tone="cyan">Interpretation ready</StatusPill></div>} />
    <div className="mt-7 grid gap-5 xl:grid-cols-[.82fr_1.18fr]">
      <Card className="p-5 md:p-6">
        <SectionTitle eyebrow="RAW WARNING INGESTION" title="Alert ingestion interface" action={<span className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">SignalCore input</span>} />
        <p className="mb-5 text-xs leading-5 text-[#71818b]">This form uses a realistic Chennai flood warning. No live official feed is connected in this phase.</p>
        <div className="space-y-3">
          <AlertField label="Alert ID" value={current?.alertId} onChange={value => updateDraft("alertId", value)} />
          <div className="grid gap-3 sm:grid-cols-2"><AlertField label="Hazard type" value={current?.hazardType} onChange={value => updateDraft("hazardType", value)} /><label className="block"><span className="font-mono text-[9px] font-semibold uppercase tracking-[.13em] text-[#84949d]">Severity</span><select value={current?.severity ?? "warning"} onChange={event => updateDraft("severity", event.target.value)} className="sb-focus mt-1.5 w-full rounded-lg border border-[#cbd9df] bg-white px-3 py-2.5 text-sm text-[#27445b]"><option value="advisory">Advisory</option><option value="watch">Watch</option><option value="warning">Warning</option><option value="critical">Critical</option></select></label></div>
          <AlertField label="Source" value={current?.source} onChange={value => updateDraft("source", value)} /><div className="grid gap-3 sm:grid-cols-2"><AlertField label="Affected area" value={current?.affectedArea} onChange={value => updateDraft("affectedArea", value)} /><label className="block"><span className="font-mono text-[9px] font-semibold uppercase tracking-[.13em] text-[#84949d]">Source status</span><select value={current?.sourceStatus ?? "simulated"} onChange={event => updateDraft("sourceStatus", event.target.value)} className="sb-focus mt-1.5 w-full rounded-lg border border-[#cbd9df] bg-white px-3 py-2.5 text-sm text-[#27445b]"><option value="simulated">Simulated</option><option value="official">Official</option><option value="connected">Connected</option></select></label></div>
          <div className="grid gap-3 sm:grid-cols-3"><AlertField label="Issue time" value={current?.issueTime} onChange={value => updateDraft("issueTime", value)} /><AlertField label="Valid from" value={current?.validFrom} onChange={value => updateDraft("validFrom", value)} /><AlertField label="Expiry time" value={current?.expiryTime} onChange={value => updateDraft("expiryTime", value)} /></div>
          <label className="block"><span className="font-mono text-[9px] font-semibold uppercase tracking-[.13em] text-[#84949d]">Warning text</span><textarea value={current?.warningText ?? ""} onChange={event => updateDraft("warningText", event.target.value)} className="sb-focus mt-1.5 min-h-[72px] w-full resize-y rounded-lg border border-[#cbd9df] bg-white px-3 py-2.5 text-sm leading-5 text-[#27445b]" /></label>
          <label className="block"><span className="font-mono text-[9px] font-semibold uppercase tracking-[.13em] text-[#84949d]">Recommended official precautions</span><textarea value={current?.recommendedPrecautions ?? ""} onChange={event => updateDraft("recommendedPrecautions", event.target.value)} className="sb-focus mt-1.5 min-h-[82px] w-full resize-y rounded-lg border border-[#cbd9df] bg-white px-3 py-2.5 text-sm leading-5 text-[#27445b]" /></label>
          <button onClick={runInterpretation} disabled={!current || interpret.isPending} className="sb-focus inline-flex w-full items-center justify-center gap-2 rounded-lg bg-[#0d3448] px-4 py-3 text-sm font-semibold text-white transition hover:bg-[#174a60] disabled:cursor-not-allowed disabled:opacity-60"><Sparkles size={16} /> {interpret.isPending ? "Interpreting…" : "Run SignalCore interpretation"}</button>
        </div>
      </Card>
      <div className="space-y-5">
        <Card className="overflow-hidden"><div className="flex flex-wrap items-start justify-between gap-3 border-b border-[#e4ebee] p-5 md:p-6"><div><div className="font-mono text-[10px] uppercase tracking-[.15em] text-[#2e8b91]">STRUCTURED ALERT OBJECT</div><h2 className="mt-2 font-display text-2xl font-semibold tracking-[-.035em] text-[#0d1b2a]">Alert Intelligence</h2></div><DemoLabel>{intelligence?.intelligenceStatus ?? "Demo interpretation"}</DemoLabel></div>{intelligence && <div className="grid gap-4 p-5 md:grid-cols-2 md:p-6"><StructuredField label="Hazard" value={intelligence.hazard} /><StructuredField label="Severity" value={intelligence.severity.toUpperCase()} tone={severityTone(intelligence.severity)} /><StructuredField label="Affected zones" value={intelligence.affectedZones.join(" · ")} /><StructuredField label="Time window" value={`${formatTime(intelligence.timeWindow.validFrom)} → ${formatTime(intelligence.timeWindow.expiryTime)} IST`} /><StructuredField label="Source" value={intelligence.source} /><StructuredField label="Source status" value={intelligence.sourceStatus.toUpperCase()} tone={intelligence.sourceStatus === "simulated" ? "amber" : "green"} /><StructuredField label="Confidence" value={`${intelligence.confidence}%`} tone={intelligence.confidence > 85 ? "green" : "amber"} /><StructuredField label="Processed" value={formatTime(intelligence.timestamp)} /><div className="md:col-span-2 rounded-lg bg-[#f4f7f9] p-4"><div className="font-mono text-[9px] font-semibold uppercase tracking-[.13em] text-[#84949d]">Extracted guidance</div><div className="mt-3 space-y-2">{intelligence.extractedInstructions.map((instruction, index) => <div key={`${instruction}-${index}`} className="flex gap-2 text-sm leading-5 text-[#27445b]"><span className="font-mono text-[10px] text-[#2e8b91]">0{index + 1}</span><span>{instruction}</span></div>)}</div></div></div>}</Card>
        <NextPhaseNotice text="This MVP uses deterministic extraction and clearly labels the result as demo intelligence. Live source ingestion, model-backed interpretation and human review are coming in next integration phase." />
      </div>
    </div>
    <div className="mt-6"><SectionTitle eyebrow="ALERT INTELLIGENCE REGISTER" title="Structured alerts" action={<span className="font-mono text-[10px] uppercase tracking-[.11em] text-[#84949d]">{warnings?.length ?? 0} records</span>} />{isLoading ? <LoadingCard /> : <Card className="overflow-hidden"><div className="hidden overflow-x-auto md:block"><table className="w-full min-w-[900px] text-left"><thead className="bg-[#f4f7f9] font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]"><tr><th className="px-5 py-3">Source</th><th className="px-5 py-3">Hazard</th><th className="px-5 py-3">Severity</th><th className="px-5 py-3">Affected area</th><th className="px-5 py-3">Validity</th><th className="px-5 py-3">Official status</th><th className="px-5 py-3">Extracted guidance</th></tr></thead><tbody className="divide-y divide-[#e4ebee]">{warnings?.map(warning => <tr key={warning.id} className="align-top"><td className="px-5 py-4"><div className="font-semibold text-[#27445b]">{warning.sourceLabel}</div><div className="mt-1 font-mono text-[10px] text-[#84949d]">{warning.alertId}</div></td><td className="px-5 py-4 text-sm text-[#27445b]">{warning.hazardType}</td><td className="px-5 py-4"><StatusPill tone={severityTone(warning.severity)}>{warning.severity}</StatusPill></td><td className="px-5 py-4 text-sm leading-5 text-[#5c6d79]">{warning.area}</td><td className="px-5 py-4 whitespace-nowrap font-mono text-[10px] text-[#71818b]">{formatTime(warning.validFrom)}–{formatTime(warning.validUntil)} IST</td><td className="px-5 py-4"><StatusPill tone={warning.sourceStatus === "simulated" ? "amber" : "green"}>{warning.sourceStatus === "simulated" ? "Demo" : warning.sourceStatus}</StatusPill></td><td className="max-w-[260px] px-5 py-4 text-sm leading-5 text-[#5c6d79]">{warning.recommendedPrecautions}</td></tr>)}</tbody></table></div><div className="space-y-3 p-4 md:hidden">{warnings?.map(warning => <div key={warning.id} className="rounded-lg border border-[#e4ebee] p-4"><div className="flex items-center justify-between gap-2"><StatusPill tone={severityTone(warning.severity)}>{warning.severity}</StatusPill><StatusPill tone={warning.sourceStatus === "simulated" ? "amber" : "green"}>{warning.sourceStatus}</StatusPill></div><div className="mt-3 font-semibold text-[#27445b]">{warning.title}</div><div className="mt-1 text-xs text-[#84949d]">{warning.sourceLabel} · {warning.area}</div><div className="mt-3 text-sm leading-5 text-[#5c6d79]">{warning.recommendedPrecautions}</div></div>)}</div></Card>}</div>
    {warnings?.map(warning => <div key={`provenance-${warning.id}`} className="mt-4"><ProvenancePanel warning={warning} /></div>)}
  </Workspace>;
}
function SourceRow({ name, type, status }: { name: string; type: string; status: string }) { return <div className="flex items-start gap-3"><span className="mt-1 h-2 w-2 rounded-full bg-[#2e8b70]" /><div className="min-w-0 flex-1"><div className="text-sm font-semibold text-[#27445b]">{name}</div><div className="mt-0.5 text-xs text-[#84949d]">{type}</div></div><span className="font-mono text-[10px] uppercase tracking-[.1em] text-[#2e8b70]">{status}</span></div>; }

export function RiskMapPage() {
  const [selectedPoint, setSelectedPoint] = useState({ lat: 13.111, lng: 80.244 });
  const { data: assessment, isFetching } = trpc.signalbridge.riskAssessment.useQuery(selectedPoint);
  return <Workspace>
    <PageHeader eyebrow="GEOSHIELD / RISK & RELEVANCE" title="Risk map" description="Select a location to determine whether it intersects a simulated warning polygon, then review the nearest relevant shelter and boundary distance." action={<div className="flex items-center gap-2"><DemoLabel>Simulated boundaries</DemoLabel><button onClick={() => setSelectedPoint({ lat: 13.111, lng: 80.244 })} className="sb-focus rounded-lg border border-[#cbd9df] bg-white px-3 py-2 text-xs font-semibold text-[#27445b] hover:border-[#7fb8bf]">Use demo location</button></div>} />
    <div className="mt-7 grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><Card className="overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#e4ebee] px-5 py-4 md:px-6"><div><div className="flex items-center gap-2 text-sm font-semibold text-[#27445b]"><MapPinned size={16} className="text-[#2e8b91]" /> Chennai metropolitan area</div><div className="mt-1 text-xs text-[#84949d]">Click the map to calculate location relevance · {isFetching ? "assessing…" : "assessment current"}</div></div><StatusPill tone={assessment?.state === "ACTION" ? "red" : assessment?.state === "WATCH" ? "amber" : "green"}>{assessment?.state ?? "Loading"}</StatusPill></div><SignalMap selectedPoint={selectedPoint} onSelectPoint={setSelectedPoint} /><div className="grid gap-3 border-t border-[#e4ebee] bg-[#f8fbfc] p-4 sm:grid-cols-2 lg:grid-cols-4"><MapLegend color="#c75252" label="ACTION" detail="Inside flood polygon" /><MapLegend color="#dd9c30" label="WATCH" detail="Inside watch polygon" /><MapLegend color="#2e8b70" label="SAFE" detail="Outside polygons" /><MapLegend color="#2e8b91" label="ROUTE" detail="Reference road" /></div></Card>
      <div className="space-y-5"><Card className="p-5 md:p-6"><div className="flex items-start justify-between gap-3"><div><div className="font-mono text-[10px] uppercase tracking-[.15em] text-[#2e8b91]">SELECTED LOCATION</div><h2 className="mt-2 font-display text-2xl font-semibold text-[#0d1b2a]">{assessment?.state ?? "Assessing…"}</h2></div><div className={`rounded-xl p-3 ${assessment?.state === "ACTION" ? "bg-[#fde5e3] text-[#8d3636]" : assessment?.state === "WATCH" ? "bg-[#fff2d4] text-[#7d5411]" : "bg-[#daf0e8] text-[#21684f]"}`}><MapPinned size={22} /></div></div>{assessment && <div className="mt-6 space-y-4"><div className="rounded-lg bg-[#f4f7f9] p-3"><div className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">Coordinates</div><div className="mt-1 font-mono text-xs text-[#27445b]">{assessment.selectedLocation.lat.toFixed(5)}, {assessment.selectedLocation.lng.toFixed(5)}</div></div><RiskDetail label="Hazard" value={assessment.hazard} /><RiskDetail label="Warning severity" value={assessment.warningSeverity.toUpperCase()} tone={assessment.state === "ACTION" ? "red" : assessment.state === "WATCH" ? "amber" : "green"} /><RiskDetail label="Affected-zone relationship" value={assessment.affectedZoneRelationship} /><RiskDetail label="Distance to boundary" value={`${assessment.distanceToAffectedBoundaryKm} km`} /><RiskDetail label="Warning validity" value={`${formatTime(assessment.warningValidity.validFrom)} → ${formatTime(assessment.warningValidity.expiryTime)} IST`} /><div className="border-t border-[#e4ebee] pt-4"><div className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">Nearest relevant shelter</div><div className="mt-2 font-semibold text-[#27445b]">{assessment.nearestShelter.name}</div><div className="mt-1 text-xs leading-5 text-[#71818b]">{assessment.nearestShelter.address} · {assessment.nearestShelter.distanceKm} km · {assessment.nearestShelter.status}</div></div></div>}</Card><Card className="p-5 md:p-6"><SectionTitle eyebrow="PROVENANCE & BOUNDARY" title="Read this result carefully" /><div className="space-y-3 text-sm leading-6 text-[#5c6d79]"><p>This assessment uses point-in-polygon intersection against the shared demonstration boundaries; the state is not a hardcoded display label.</p><p className="font-semibold text-[#7d5411]">{assessment?.disclaimer ?? "Simulated hazard boundaries for product demonstration only. This is not a real-time emergency prediction system."}</p></div></Card><NextPhaseNotice text="Live geocoding, official GIS boundaries, shelter capacity sync and route-aware travel distance are coming in next integration phase." /></div></div>
  </Workspace>;
}
function LegendRow({ color, label, detail }: { color: string; label: string; detail: string }) { return <div className="flex items-center gap-3"><span className="h-3 w-3 rounded-full" style={{ background: color }} /><div><div className="text-sm font-semibold text-[#27445b]">{label}</div><div className="text-xs text-[#84949d]">{detail}</div></div></div>; }
function Note({ icon, text, tone }: { icon: React.ReactNode; text: string; tone: "red" | "amber" | "green" }) { const colors = { red: "bg-[#fde5e3] text-[#8d3636]", amber: "bg-[#fff2d4] text-[#7d5411]", green: "bg-[#daf0e8] text-[#21684f]" }; return <div className="flex items-center gap-3 rounded-lg bg-[#f4f7f9] p-3"><span className={`rounded-md p-2 ${colors[tone]}`}>{icon}</span><span className="text-sm font-medium text-[#27445b]">{text}</span></div>; }

function AlertField({ label, value, onChange }: { label: string; value?: string; onChange: (value: string) => void }) { return <label className="block"><span className="font-mono text-[9px] font-semibold uppercase tracking-[.13em] text-[#84949d]">{label}</span><input value={value ?? ""} onChange={event => onChange(event.target.value)} className="sb-focus mt-1.5 w-full rounded-lg border border-[#cbd9df] bg-white px-3 py-2.5 text-sm text-[#27445b]" /></label>; }
function StructuredField({ label, value, tone }: { label: string; value: string; tone?: "red" | "amber" | "green" | "cyan" }) { return <div className="rounded-lg bg-[#f4f7f9] p-3"><div className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">{label}</div><div className="mt-1.5 flex items-center gap-2 text-sm font-semibold text-[#27445b]">{tone ? <StatusPill tone={tone}>{value}</StatusPill> : value}</div></div>; }
function ProvenancePanel({ warning }: { warning: { alertId: string; sourceLabel: string; sourceStatus: string; issuedAt: Date | string; validFrom: Date | string; validUntil: Date | string | null; warningText: string; recommendedPrecautions: string } }) { return <Card className="overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#e4ebee] bg-[#f8fbfc] px-5 py-3 md:px-6"><div className="flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-[#2e8b91]" /><span className="font-mono text-[10px] font-semibold uppercase tracking-[.14em] text-[#27445b]">Source provenance · {warning.alertId}</span></div><StatusPill tone={warning.sourceStatus === "simulated" ? "amber" : "green"}>{warning.sourceStatus === "simulated" ? "Demo source" : warning.sourceStatus}</StatusPill></div><div className="grid gap-4 p-5 text-sm md:grid-cols-4 md:px-6"><div><div className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">Source</div><div className="mt-1 font-semibold text-[#27445b]">{warning.sourceLabel}</div></div><div><div className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">Issued / valid</div><div className="mt-1 text-[#5c6d79]">{formatTime(warning.issuedAt)} / {formatTime(warning.validFrom)}–{formatTime(warning.validUntil)} IST</div></div><div><div className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">Raw warning</div><div className="mt-1 text-[#5c6d79]">{warning.warningText}</div></div><div><div className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">Recommended precautions</div><div className="mt-1 text-[#5c6d79]">{warning.recommendedPrecautions}</div></div></div></Card>; }
function MapLegend({ color, label, detail }: { color: string; label: string; detail: string }) { return <div className="flex items-center gap-2"><span className="h-2.5 w-2.5 rounded-full" style={{ background: color }} /><div><div className="font-mono text-[9px] font-semibold tracking-[.11em] text-[#27445b]">{label}</div><div className="text-[10px] text-[#84949d]">{detail}</div></div></div>; }
function RiskDetail({ label, value, tone }: { label: string; value: string; tone?: "red" | "amber" | "green" }) { return <div className="flex items-start justify-between gap-4 border-b border-[#eef2f4] pb-3"><div className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">{label}</div>{tone ? <StatusPill tone={tone}>{value}</StatusPill> : <div className="max-w-[62%] text-right text-sm font-semibold leading-5 text-[#27445b]">{value}</div>}</div>; }
export function ActionPlansPage() { const { data, isLoading } = trpc.signalbridge.actionPlans.useQuery(); const [statuses, setStatuses] = useState<Record<number, string>>({}); const plans = data?.map(plan => ({ ...plan, status: statuses[plan.id] ?? plan.status })) ?? []; const complete = plans.filter(p => p.status === "complete").length; return <Workspace><PageHeader eyebrow="ACTIONFORGE / SAFE ACTION" title="Action plans" description="A clear, prioritized sequence compiled from the current warning, location context and emergency profile." action={<DemoLabel />} /><div className="mt-7 grid gap-5 lg:grid-cols-[1fr_.37fr]"><Card className="p-5 md:p-7"><div className="flex flex-wrap items-end justify-between gap-3 border-b border-[#e4ebee] pb-5"><div><div className="font-mono text-[10px] uppercase tracking-[.14em] text-[#84949d]">Current plan readiness</div><div className="mt-2 font-display text-3xl font-semibold tracking-[-.04em] text-[#0d1b2a]">{complete} / {plans.length} <span className="text-base font-medium tracking-normal text-[#71818b]">steps complete</span></div></div><div className="w-full max-w-[220px]"><ProgressBar value={plans.length ? (complete / plans.length) * 100 : 0} color="#2e8b70" /><div className="mt-2 text-right font-mono text-[10px] text-[#84949d]">Updated from current snapshot</div></div></div><div className="mt-6 space-y-3">{isLoading ? <LoadingCard /> : plans.map((plan, index) => <div key={plan.id} className={`rounded-xl border p-4 transition ${plan.status === "complete" ? "border-[#c7e1d6] bg-[#f5fbf8]" : plan.priority === "now" ? "border-[#ead3d0] bg-[#fffafa]" : "border-[#e4ebee] bg-white"}`}><div className="flex gap-4"><div className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-full font-mono text-xs font-semibold ${plan.status === "complete" ? "bg-[#daf0e8] text-[#21684f]" : plan.priority === "now" ? "bg-[#fde5e3] text-[#8d3636]" : "bg-[#e8eef4] text-[#27445b]"}`}>{plan.status === "complete" ? <Check size={16} /> : `0${index + 1}`}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-start justify-between gap-2"><div><div className="flex flex-wrap items-center gap-2"><h3 className="font-semibold text-[#27445b]">{plan.title}</h3><StatusPill tone={priorityTone(plan.priority)}>{plan.priority}</StatusPill></div><div className="mt-2 text-sm leading-6 text-[#5c6d79]">{plan.description}</div></div><button onClick={() => setStatuses(prev => ({ ...prev, [plan.id]: plan.status === "complete" ? "pending" : "complete" }))} className="sb-focus inline-flex shrink-0 items-center gap-1.5 rounded-lg border border-[#cbd9df] bg-white px-3 py-2 text-xs font-semibold text-[#27445b] hover:border-[#7fb8bf]">{plan.status === "complete" ? "Reopen" : "Mark complete"}</button></div><div className="mt-3 flex flex-wrap items-center gap-4 border-t border-[#e4ebee] pt-3 font-mono text-[10px] uppercase tracking-[.1em] text-[#84949d]"><span>{plan.category}</span><span>Due: {plan.dueBy}</span><span className={plan.status === "complete" ? "text-[#2e8b70]" : "text-[#7d5411]"}>{plan.status === "complete" ? "Complete" : "Open"}</span></div></div></div></div>)}</div></Card><div className="space-y-5"><Card className="p-5 md:p-6"><SectionTitle eyebrow="ACCESSBRIDGE" title="Plan accessibility" /><div className="space-y-4"><div className="flex items-center gap-3"><span className="rounded-lg bg-[#d9f1f0] p-2 text-[#0d5960]"><Languages size={17} /></span><div><div className="text-sm font-semibold text-[#27445b]">English</div><div className="text-xs text-[#84949d]">Current profile preference</div></div></div><div className="flex items-center gap-3"><span className="rounded-lg bg-[#e8eef4] p-2 text-[#27445b]"><FileText size={17} /></span><div><div className="text-sm font-semibold text-[#27445b]">Plain-language steps</div><div className="text-xs text-[#84949d]">No AI rewriting applied</div></div></div></div></Card><NextPhaseNotice text="Tamil generation, voice output, adjustable reading modes and offline plan sync are coming in next integration phase." /></div></div></Workspace>; }

export function EvidencePage() { const { data, isLoading } = trpc.signalbridge.evidence.useQuery(); return <Workspace><PageHeader eyebrow="TRUSTMESH / EVIDENCE" title="Evidence center" description="Understand which sources support each warning, how current they are, and where uncertainty remains." action={<div className="flex gap-2"><DemoLabel /><StatusPill tone="green">3 linked items</StatusPill></div>} /><div className="mt-7 grid gap-5 lg:grid-cols-[1fr_.34fr]"><div className="space-y-4">{isLoading ? <LoadingCard /> : data?.map(item => <Card key={item.id} className="p-5 md:p-6"><div className="flex flex-wrap items-start justify-between gap-3"><div className="flex items-center gap-2"><StatusPill tone={item.confidence > 85 ? "green" : "amber"}>{item.confidence}% confidence</StatusPill><span className="font-mono text-[10px] uppercase tracking-[.1em] text-[#84949d]">{item.evidenceType}</span></div><span className="font-mono text-[10px] text-[#84949d]">{formatDate(item.publishedAt)}</span></div><h2 className="mt-4 font-display text-xl font-semibold text-[#0d1b2a]">{item.title}</h2><div className="mt-1 text-xs font-medium text-[#2e8b91]">{item.publisher}</div><p className="mt-3 text-sm leading-6 text-[#5c6d79]">{item.summary}</p><div className="mt-5 flex items-center justify-between gap-3 border-t border-[#e4ebee] pt-4"><div className="flex items-center gap-2 text-xs text-[#71818b]"><LockKeyhole size={14} className="text-[#2e8b70]" /> Source metadata retained</div>{item.url ? <a href={item.url} target="_blank" rel="noreferrer" className="sb-focus inline-flex items-center gap-1.5 text-xs font-semibold text-[#2e8b91] hover:underline">Open source <ExternalLink size={13} /></a> : <span className="font-mono text-[10px] uppercase tracking-[.1em] text-[#a3afb5]">Community signal</span>}</div></Card>)}</div><div className="space-y-5"><Card className="p-5 md:p-6"><SectionTitle eyebrow="UNCERTAINTY" title="How to read the score" /><div className="space-y-4 text-sm leading-6 text-[#5c6d79]"><p><span className="font-semibold text-[#27445b]">90–100%</span> indicates a current official or corroborated signal.</p><p><span className="font-semibold text-[#27445b]">70–89%</span> indicates useful supporting context that should be watched for changes.</p><p><span className="font-semibold text-[#27445b]">Below 70%</span> is a lead, not a standalone reason to act.</p></div></Card><NextPhaseNotice text="Cross-source conflict detection and human-review workflows are coming in next integration phase." /></div></div></Workspace>; }

export function CitizenIntelligencePage() { const { data, isLoading } = trpc.signalbridge.citizenReports.useQuery(); const [filter, setFilter] = useState("all"); const reports = useMemo(() => data?.filter(report => filter === "all" || report.verificationStatus === filter) ?? [], [data, filter]); return <Workspace><PageHeader eyebrow="CROWDPULSE / COMMUNITY" title="Citizen intelligence" description="A triage view of community-reported conditions. Citizen signals add context; they do not replace official warnings." action={<button onClick={() => toast.info("Report intake", { description: "Structured citizen reporting is coming in next integration phase." })} className="sb-focus inline-flex items-center gap-2 rounded-lg bg-[#0d3448] px-3.5 py-2.5 text-xs font-semibold text-white hover:bg-[#174a60]"><MessageSquareWarning size={15} /> Report an incident</button>} /><div className="mt-7 flex flex-wrap items-center justify-between gap-3"><div className="flex flex-wrap gap-2">{[["all", "All signals"], ["corroborated", "Corroborated"], ["triaged", "Triaged"], ["unverified", "Unverified"]].map(([value, label]) => <button key={value} onClick={() => setFilter(value)} className={`sb-focus rounded-full px-3 py-1.5 text-xs font-semibold transition ${filter === value ? "bg-[#0d3448] text-white" : "border border-[#cbd9df] bg-white text-[#5c6d79] hover:border-[#7fb8bf]"}`}>{label}</button>)}</div><DemoLabel>Community data</DemoLabel></div><div className="mt-5 grid gap-4 lg:grid-cols-3">{isLoading ? <LoadingCard /> : reports.map(report => <Card key={report.id} className="flex flex-col p-5"><div className="flex items-center justify-between gap-2"><StatusPill tone={severityTone(report.severity)}>{report.severity}</StatusPill><span className="font-mono text-[10px] text-[#84949d]">{formatTime(report.reportedAt)} IST</span></div><div className="mt-4 flex items-start gap-2"><MapPinned size={16} className="mt-0.5 shrink-0 text-[#2e8b91]" /><h2 className="font-display text-lg font-semibold leading-6 text-[#0d1b2a]">{report.locationName}</h2></div><div className="mt-1 font-mono text-[10px] uppercase tracking-[.11em] text-[#84949d]">{report.category}</div><p className="mt-3 flex-1 text-sm leading-6 text-[#5c6d79]">{report.summary}</p><div className="mt-5 flex items-center justify-between border-t border-[#e4ebee] pt-4"><span className={`font-mono text-[10px] uppercase tracking-[.1em] ${report.verificationStatus === "corroborated" ? "text-[#2e8b70]" : report.verificationStatus === "triaged" ? "text-[#7d5411]" : "text-[#84949d]"}`}>{report.verificationStatus}</span><span className="flex items-center gap-1.5 text-xs text-[#71818b]"><UsersRound size={13} /> {report.upvotes} signals</span></div></Card>)}</div><div className="mt-5"><NextPhaseNotice text="Report submission, clustering, duplicate detection and media evidence review are coming in next integration phase." /></div></Workspace>; }

export function ProfilePage() { const { data, isLoading } = trpc.signalbridge.profile.useQuery(); return <Workspace><PageHeader eyebrow="PERSONAL / PROFILE" title="Emergency profile" description="The context SignalBridge uses to make safe actions more relevant to your household and access needs." action={<button onClick={() => toast.info("Profile editing", { description: "Profile persistence is coming in next integration phase." })} className="sb-focus inline-flex items-center gap-2 rounded-lg border border-[#cbd9df] bg-white px-3.5 py-2.5 text-xs font-semibold text-[#27445b] hover:border-[#7fb8bf]"><UserRound size={15} /> Edit profile</button>} /><div className="mt-7 grid gap-5 lg:grid-cols-[.9fr_1.1fr]"><Card className="p-5 md:p-7"><div className="flex items-center gap-4 border-b border-[#e4ebee] pb-6"><div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-[#d9f1f0] font-display text-xl font-semibold text-[#0d5960]">AM</div><div><div className="font-display text-xl font-semibold text-[#0d1b2a]">{isLoading ? "Loading…" : data?.displayName}</div><div className="mt-1 flex items-center gap-1.5 text-sm text-[#71818b]"><MapPinned size={14} className="text-[#2e8b91]" /> {data?.homeArea}</div></div></div><div className="mt-6 space-y-5"><ProfileRow label="Household" value={`${data?.householdSize ?? "—"} people`} /><ProfileRow label="Access needs" value={data?.mobilityNeeds ?? "Not recorded"} /><ProfileRow label="Preferred language" value={data?.preferredLanguage ?? "English"} /><ProfileRow label="Emergency contact" value={data?.emergencyContact ?? "Not recorded"} icon={<PhoneCall size={14} />} /></div></Card><div className="space-y-5"><Card className="p-5 md:p-7"><SectionTitle eyebrow="WHY IT MATTERS" title="Personalization without guesswork" /><div className="space-y-4"><Reason icon={<Navigation size={17} />} title="Route context" detail="Step-free route preferences can shape which actions appear first." /><Reason icon={<UsersRound size={17} />} title="Household context" detail="The plan can account for the number of people who need to move together." /><Reason icon={<Languages size={17} />} title="Accessible delivery" detail="Language and format preferences make the same warning easier to use." /></div></Card><NextPhaseNotice text="Profile editing, verified contact workflows and additional accessibility preferences are coming in next integration phase." /></div></div></Workspace>; }
function ProfileRow({ label, value, icon }: { label: string; value: string; icon?: React.ReactNode }) { return <div className="flex items-start justify-between gap-4"><div className="font-mono text-[10px] uppercase tracking-[.13em] text-[#84949d]">{label}</div><div className="flex max-w-[58%] items-center gap-1.5 text-right text-sm font-semibold text-[#27445b]">{icon}{value}</div></div>; }
function Reason({ icon, title, detail }: { icon: React.ReactNode; title: string; detail: string }) { return <div className="flex gap-3"><span className="rounded-lg bg-[#e8eef4] p-2 text-[#27445b]">{icon}</span><div><div className="text-sm font-semibold text-[#27445b]">{title}</div><div className="mt-1 text-xs leading-5 text-[#71818b]">{detail}</div></div></div>; }

export function SafetyPage() { const { data } = trpc.signalbridge.safety.useQuery(); const safety = data ?? { state: "needs_check_in", lastCheckIn: "2026-09-22T05:55:00Z", nextCheckIn: "By 07:15 IST", message: "Your last check-in was 42 minutes ago. Confirm that you are safe or request assistance." }; const [state, setState] = useState(safety.state); const [lastMessage, setLastMessage] = useState(""); const isSafe = state === "safe"; const requestHelp = () => { setState("assistance_requested"); setLastMessage("Assistance request staged for this demo session."); toast.success("Assistance request staged", { description: "A real responder handoff is coming in next integration phase." }); }; return <Workspace><PageHeader eyebrow="SAFELOOP / STATUS" title="Safety status" description="Close the loop after a warning. Your status helps responders and trusted contacts know whether more support is needed." action={<DemoLabel />} /><div className="mt-7 grid gap-5 lg:grid-cols-[1fr_.72fr]"><Card className={`overflow-hidden ${isSafe ? "border-[#c7e1d6]" : state === "assistance_requested" ? "border-[#ead3d0]" : "border-[#ead9ae]"}`}><div className={`p-6 md:p-8 ${isSafe ? "bg-[#f5fbf8]" : state === "assistance_requested" ? "bg-[#fffafa]" : "bg-[#fffaf0]"}`}><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-3"><div className={`flex h-12 w-12 items-center justify-center rounded-2xl ${isSafe ? "bg-[#daf0e8] text-[#21684f]" : state === "assistance_requested" ? "bg-[#fde5e3] text-[#8d3636]" : "bg-[#fff2d4] text-[#7d5411]"}`}>{isSafe ? <CheckCircle2 size={24} /> : state === "assistance_requested" ? <PhoneCall size={24} /> : <ShieldAlert size={24} />}</div><div><div className="font-mono text-[10px] uppercase tracking-[.15em] text-[#84949d]">Current status</div><div className="mt-1 font-display text-2xl font-semibold text-[#0d1b2a]">{isSafe ? "You are safe" : state === "assistance_requested" ? "Assistance requested" : "Check-in needed"}</div></div></div><StatusPill tone={isSafe ? "green" : state === "assistance_requested" ? "red" : "amber"}>{state.replaceAll("_", " ")}</StatusPill></div><p className="mt-7 max-w-[600px] text-sm leading-6 text-[#5c6d79]">{lastMessage || safety.message}</p><div className="mt-7 flex flex-wrap gap-3"><button onClick={() => { setState("safe"); setLastMessage("Check-in received. Your status is current for the next monitoring window."); toast.success("You're marked safe"); }} className="sb-focus inline-flex items-center gap-2 rounded-lg bg-[#0d3448] px-4 py-3 text-sm font-semibold text-white hover:bg-[#174a60]"><CheckCircle2 size={17} /> I am safe</button><button onClick={requestHelp} className="sb-focus inline-flex items-center gap-2 rounded-lg border border-[#d7b4af] bg-white px-4 py-3 text-sm font-semibold text-[#8d3636] hover:border-[#b97b72]"><PhoneCall size={17} /> Request assistance</button></div></div><div className="grid gap-4 border-t border-[#e4ebee] p-6 sm:grid-cols-3 md:p-8"><div><div className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">Last check-in</div><div className="mt-2 text-sm font-semibold text-[#27445b]">{formatTime(safety.lastCheckIn)} IST</div></div><div><div className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">Next check-in</div><div className="mt-2 text-sm font-semibold text-[#27445b]">{safety.nextCheckIn}</div></div><div><div className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">Privacy</div><div className="mt-2 flex items-center gap-1.5 text-sm font-semibold text-[#2e8b70]"><LockKeyhole size={14} /> You control sharing</div></div></div></Card><div className="space-y-5"><Card className="p-5 md:p-6"><SectionTitle eyebrow="RESPONSE LOOP" title="What happens next" /><div className="space-y-4"><TimelineStep number="01" title="You check in" detail="Your status is timestamped for this monitoring window." done={isSafe || state === "assistance_requested"} /><TimelineStep number="02" title="SignalBridge keeps watching" detail="The current warning and local risk context remain visible." done /><TimelineStep number="03" title="A responder handoff" detail="Human responder workflows are added in a later phase." /></div></Card><NextPhaseNotice text="Responder escalation, trusted-contact notifications and real check-in persistence are coming in next integration phase." /></div></div></Workspace>; }
function TimelineStep({ number, title, detail, done }: { number: string; title: string; detail: string; done?: boolean }) { return <div className="flex gap-3"><div className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full font-mono text-[10px] font-semibold ${done ? "bg-[#daf0e8] text-[#21684f]" : "bg-[#e8eef4] text-[#71818b]"}`}>{done ? <Check size={14} /> : number}</div><div><div className="text-sm font-semibold text-[#27445b]">{title}</div><div className="mt-1 text-xs leading-5 text-[#84949d]">{detail}</div></div></div>; }

export function OfflinePage() { const downloadCard = () => { const content = ["SIGNALBRIDGE · OFFLINE EMERGENCY CARD", "CHENNAI / URBAN FLOOD DEMO", "", "1. Move to a higher floor or safer nearby building.", "2. Avoid underpasses and moving water.", "3. Carry medication, torch, water and a charged phone.", "4. Share your location with your emergency contact.", "5. If in immediate danger, contact local emergency services.", "", "This card is a prototype and does not replace official emergency guidance."]; const blob = new Blob([content.join("\n")], { type: "text/plain" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "signalbridge-offline-card.txt"; anchor.click(); URL.revokeObjectURL(url); toast.success("Offline card downloaded"); }; return <Workspace><PageHeader eyebrow="RESILIENCEVAULT / OFFLINE" title="Offline emergency mode" description="A compact, readable set of actions to keep available when connectivity becomes unreliable." action={<button onClick={downloadCard} className="sb-focus inline-flex items-center gap-2 rounded-lg bg-[#0d3448] px-3.5 py-2.5 text-xs font-semibold text-white hover:bg-[#174a60]"><Download size={15} /> Download field card</button>} /><div className="mt-7 grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><Card className="p-5 md:p-7"><div className="flex items-center gap-3"><div className="rounded-xl bg-[#d9f1f0] p-3 text-[#0d5960]"><WifiOff size={22} /></div><div><div className="font-mono text-[10px] uppercase tracking-[.15em] text-[#2e8b91]">Local cache ready</div><div className="mt-1 font-display text-xl font-semibold text-[#0d1b2a]">Core actions available</div></div></div><div className="mt-7 space-y-3"><OfflineRow number="01" title="Get to higher ground" /><OfflineRow number="02" title="Avoid moving water and underpasses" /><OfflineRow number="03" title="Keep medication and phone with you" /><OfflineRow number="04" title="Check in with your trusted contact" /></div><div className="mt-7 rounded-lg bg-[#fff8e8] p-3 text-xs leading-5 text-[#7d5411]">Offline content is intentionally concise. It does not include live warnings, routing or responder handoff.</div></Card><Card className="overflow-hidden"><div className="flex items-center justify-between border-b border-[#e4ebee] px-5 py-4 md:px-6"><div><div className="font-mono text-[10px] uppercase tracking-[.15em] text-[#84949d]">Emergency field card</div><div className="mt-1 font-display text-xl font-semibold text-[#0d1b2a]">If the signal drops</div></div><StatusPill tone="cyan">Readable offline</StatusPill></div><div className="grid gap-px bg-[#e4ebee] sm:grid-cols-2">{[["01", "Move early", "Do not wait for water to enter the home."], ["02", "Stay visible", "Use a torch and keep footwear on."], ["03", "Keep it short", "Send location + destination if messaging."], ["04", "Ask for help", "Call local emergency services if in danger."]].map(([number, title, detail]) => <div key={number} className="bg-white p-6"><div className="font-mono text-xs text-[#2e8b91]">{number}</div><div className="mt-8 font-display text-lg font-semibold text-[#0d1b2a]">{title}</div><div className="mt-2 text-sm leading-6 text-[#5c6d79]">{detail}</div></div>)}</div></Card></div><div className="mt-5"><NextPhaseNotice text="Automatic offline caching, Tamil field cards, voice prompts and background sync are coming in next integration phase." /></div></Workspace>; }
function OfflineRow({ number, title }: { number: string; title: string }) { return <div className="flex items-center gap-3 rounded-lg border border-[#e4ebee] p-3"><span className="font-mono text-xs text-[#2e8b91]">{number}</span><span className="text-sm font-semibold text-[#27445b]">{title}</span><Check size={15} className="ml-auto text-[#2e8b70]" /></div>; }

export function SettingsPage() { const [notifications, setNotifications] = useState(true); const [reducedMotion, setReducedMotion] = useState(false); const [language, setLanguage] = useState("English"); return <Workspace><PageHeader eyebrow="SYSTEM / PREFERENCES" title="Settings" description="Adjust the foundation experience. Some integrations are intentionally staged for a later phase." action={<StatusPill tone="slate">Foundation v0.1</StatusPill>} /><div className="mt-7 grid gap-5 lg:grid-cols-[1fr_.7fr]"><Card className="divide-y divide-[#e4ebee]"><SettingRow icon={<Bell size={17} />} title="Emergency alert notifications" description="Keep current warning updates visible in this workspace." control={<button onClick={() => setNotifications(!notifications)} className={`sb-focus relative h-6 w-11 rounded-full transition ${notifications ? "bg-[#2e8b91]" : "bg-[#cbd9df]"}`} aria-label="Toggle emergency alert notifications"><span className={`absolute top-1 h-4 w-4 rounded-full bg-white shadow transition ${notifications ? "left-6" : "left-1"}`} /></button>} /><SettingRow icon={<Languages size={17} />} title="Preferred language" description="Used for future accessible action-plan output." control={<select value={language} onChange={event => setLanguage(event.target.value)} className="sb-focus rounded-lg border border-[#cbd9df] bg-white px-3 py-2 text-xs font-semibold text-[#27445b]"><option>English</option><option>Tamil (next phase)</option></select>} /><SettingRow icon={<SlidersHorizontal size={17} />} title="Reduced motion" description="Respect a lower-motion presentation for interface transitions." control={<button onClick={() => setReducedMotion(!reducedMotion)} className={`sb-focus relative h-6 w-11 rounded-full transition ${reducedMotion ? "bg-[#2e8b91]" : "bg-[#cbd9df]"}`} aria-label="Toggle reduced motion"><span className={`absolute top-1 h-4 w-4 rounded-full bg-white shadow transition ${reducedMotion ? "left-6" : "left-1"}`} /></button>} /><SettingRow icon={<Wifi size={17} />} title="Connectivity diagnostics" description="Last sync 06:32 IST · Stable in this demo session." control={<button onClick={() => toast.success("Connection check complete", { description: "SignalBridge demo connection is stable." })} className="sb-focus inline-flex items-center gap-1.5 rounded-lg border border-[#cbd9df] bg-white px-3 py-2 text-xs font-semibold text-[#27445b] hover:border-[#7fb8bf]"><RefreshCw size={13} /> Check</button>} /></Card><div className="space-y-5"><Card className="p-5 md:p-6"><SectionTitle eyebrow="PRODUCT BOUNDARY" title="What is not connected yet" /><div className="space-y-3 text-sm leading-6 text-[#5c6d79]"><div className="flex gap-2"><span className="text-[#dd9c30]">—</span><span>OpenRouter or any external AI provider</span></div><div className="flex gap-2"><span className="text-[#dd9c30]">—</span><span>Live government alert feeds</span></div><div className="flex gap-2"><span className="text-[#dd9c30]">—</span><span>Responder and contact escalation</span></div></div></Card><NextPhaseNotice /></div></div></Workspace>; }
function SettingRow({ icon, title, description, control }: { icon: React.ReactNode; title: string; description: string; control: React.ReactNode }) { return <div className="flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between md:p-6"><div className="flex gap-3"><span className="rounded-lg bg-[#e8eef4] p-2 text-[#27445b]">{icon}</span><div><div className="text-sm font-semibold text-[#27445b]">{title}</div><div className="mt-1 max-w-[530px] text-xs leading-5 text-[#84949d]">{description}</div></div></div>{control}</div>; }
